<?php

declare(strict_types=1);

$grants = $grantsByUser[$account['id']] ?? [];
$changes = $permissionHistoryByUser[$account['id']] ?? [];
?>
<section class="mt-6 border-t border-slate-200 pt-5" aria-labelledby="permisos-<?= $account['id'] ?>"><h3 id="permisos-<?= $account['id'] ?>" class="font-bold">Permisos adicionales del técnico</h3><p class="mt-1 text-sm text-slate-600">Desactivados por defecto. Solo el Responsable CSI puede cambiarlos.</p><div class="mt-4 grid gap-3 sm:grid-cols-2">
<?php foreach (\App\Application\Authentication\ChangeUserPermission::GRANTABLE as $code => $label): $enabled = in_array($code, $grants, true); ?><form method="post" action="/csi/users/<?= $account['id'] ?>/permissions?page=<?= $listing['page'] ?>" class="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-slate-200 p-3"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="permission" value="<?= $e($code) ?>"><input type="hidden" name="enabled" value="<?= $enabled ? '0' : '1' ?>"><div><p class="text-sm font-semibold"><?= $e($label) ?></p><p class="text-xs text-slate-600"><?= $enabled ? 'Autorizado' : 'Sin autorizar' ?></p></div><button type="submit" class="min-h-11 rounded-lg border border-institutional-700 px-4 text-sm font-bold text-institutional-700 hover:bg-institutional-50 focus-visible:ring-2 focus-visible:ring-institutional-700"><?= $enabled ? 'Revocar' : 'Conceder' ?></button></form><?php endforeach; ?></div>
<?php if ($changes !== []): ?><details class="mt-4 text-sm"><summary class="cursor-pointer font-semibold text-institutional-700">Ver cambios de permisos</summary><ol class="mt-3 space-y-2"><?php foreach (array_slice($changes, 0, 10) as $change): ?><li class="rounded-lg bg-slate-50 p-3"><?= $change['action'] === 'granted' ? 'Concedido' : 'Revocado' ?>: <?= $e(\App\Application\Authentication\ChangeUserPermission::GRANTABLE[$change['permission_code']] ?? $change['permission_code']) ?> · <?= $e($change['actor_name'] ?? 'Cuenta anterior') ?> · <?= $e((new DateTimeImmutable($change['created_at']))->setTimezone(new DateTimeZone('America/Lima'))->format('d/m/Y H:i')) ?></li><?php endforeach; ?></ol></details><?php endif; ?></section>
